def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'

    last_my, last_opp = history[-1]
    opp_d = 0
    recent5_d = 0
    recent10_d = 0

    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1
            if i >= n - 5:
                recent5_d += 1
            if i >= n - 10:
                recent10_d += 1

    opp_c = n - opp_d

    if opp_d * 3 >= n * 2:
        return 'D'
    if n >= 5 and recent5_d >= 4:
        return 'D'
    if n >= 10 and recent10_d >= 7:
        return 'D'

    if opp_d == 0:
        if n >= 95:
            return 'D'
        if n == 90 and last_my == 'C':
            return 'D'

    nice = opp_c >= 2 * opp_d

    if nice:
        if last_opp == 'D':
            if last_my == 'C':
                if (
                    n >= 2
                    and history[-2][0] == 'D'
                    and history[-2][1] == 'C'
                    and recent5_d <= 2
                ):
                    return 'C'
                return 'D'
            else:
                if n >= 2:
                    prev_my, prev_opp = history[-2]
                    if recent5_d <= 2 and (
                        (prev_my == 'D' and prev_opp == 'C')
                        or (prev_my == 'D' and prev_opp == 'D')
                    ):
                        return 'C'
                return 'D'
        else:
            return 'C'
    else:
        if last_opp == 'D':
            return 'D'
        if n >= 10 and recent10_d >= 4:
            return 'D'
        return 'C'
